 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "mode": "filter",
 "query": "invoice retention purge refund"
}

{
 "command": "cat .engramdb/memories/invoice-retention-period*.md && cat migrations/0001_create_invoices.sql migrations/0005_create_refunds.sql migrations/0003_add_ledger_ref.sql && cat scripts/backfill_tax.py scripts/export.py && cat src/billing/refunds.py && grep -rn -i \"retention\\|purge\\|3650\\|RETENTION\" --exclude-dir=.engramdb . ; cat docs/ops/backfills.md; grep -n -i -A5 \"purge\\|retention\\|script\" docs/runbook.md",
 "description": "Read retention memories, schema, scripts, docs"
}

{
 "command": "cat migrations/0004_create_lines.sql migrations/0007_add_customers.sql pyproject.toml tests/test_db.py scripts/migrate_dev.py; sed -n 19,60p docs/runbook.md; grep -rn \"structlog\\|psycopg\\|DATABASE_URL\" src scripts | head -20",
 "description": "Read lines schema, deps, db patterns"
}

{
 "command": "python -m py_compile scripts/purge_invoices.py && env -u DATABASE_URL python scripts/purge_invoices.py; echo \"exit=$?\"; python scripts/purge_invoices.py --batch-size 2000; echo \"exit=$?\"; python -c \"import psycopg\" 2>&1 | tail -1",
 "description": "Compile and smoke-test the script"
}

